import numpy as np
import matplotlib.pyplot as plt
from scipy import stats

def task_func(original):
    def _extract_numeric(obj, out):
        if isinstance(obj, (int, float, np.integer, np.floating)) and not isinstance(obj, bool):
            out.append(float(obj))
        elif isinstance(obj, (list, tuple, np.ndarray)):
            for item in obj:
                _extract_numeric(item, out)

    values = []
    _extract_numeric(original, values)
    arr = np.asarray(values, dtype=float)

    if arr.size > 0:
        mean = float(np.mean(arr))
        std = float(np.std(arr))
        minimum = float(np.min(arr))
        maximum = float(np.max(arr))
    else:
        mean = std = minimum = maximum = np.nan

    stats_dict = {
        "mean": mean,
        "std": std,
        "min": minimum,
        "max": maximum,
    }

    fig, ax = plt.subplots()

    if arr.size > 0:
        ax.hist(arr, bins="auto", density=True, alpha=0.6)

        if np.isfinite(std) and std > 0:
            x = np.linspace(np.min(arr), np.max(arr), 200)
            y = stats.norm.pdf(x, loc=mean, scale=std)
            ax.plot(x, y, linewidth=2)
        else:
            ax.axvline(mean, linewidth=2)
    else:
        ax.hist(arr, bins="auto", density=True, alpha=0.6)

    ax.set_xlabel("Value")
    ax.set_ylabel("Density")

    return arr, stats_dict, ax
